function renderTools(){const chips=categoryTabs(),foodTabs=tab==='recipes'?`<div class="food-tabs" role="tablist" aria-label="Food"><button class="chip ${foodView==='recipes'?'active':''}" data-food-view="recipes" role="tab" aria-selected="${foodView==='recipes'}">Recipes</button><button class="chip ${foodView==='ingredients'?'active':''}" data-food-view="ingredients" role="tab" aria-selected="${foodView==='ingredients'}">Ingredients</button></div>`:'';const searchLabel=tab==='recipes'?(foodView==='ingredients'?'ingredients':'recipes'):titles[tab].toLowerCase();$('#tools').innerHTML=(tab==='todos'||tab==='cars')?'':`${foodTabs}<input class="search" type="search" placeholder="Search ${searchLabel}" aria-label="Search ${searchLabel}" value="${e(query)}">${chips.length?`<div class="chips category-tabs" role="tablist" aria-label="${tab==='notes'?'Note':'Recipe'} categories">${chips.map(([v,l])=>`<button class="chip ${filter===v?'active':''}" data-filter="${e(v)}" role="tab" aria-selected="${filter===v}">${e(l)}</button>`).join('')}</div>`:''}${tab==='recipes'&&foodView==='ingredients'?'<button class="secondary manage-tags" id="manageTags">Manage tags</button>':''}`;const search=$('.search');if(search)search.oninput=ev=>{query=ev.target.value;writeViewHistory(true);clearTimeout(searchTimer);searchTimer=setTimeout(renderList,120)};$$('[data-food-view]').forEach(button=>button.onclick=()=>{if(foodView===button.dataset.foodView&&!selected)return;foodView=button.dataset.foodView;filter='all';query='';selected=null;writeViewHistory();render()});$$('[data-filter]').forEach(button=>button.onclick=()=>setCategoryFilter(button.dataset.filter));const active=$('.category-tabs .chip.active');if(active)requestAnimationFrame(()=>active.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'}));$('#manageTags')?.addEventListener('click',manageIngredientTags)}
function renderList(){if(tab==='settings'||$('#app').hidden)return;if(!loaded){commitList('<p class="loading">Loading your journal…</p>');return}if(tab==='todos'){renderTodos();return}if(tab==='recipes'&&foodView==='ingredients'){renderIngredientList();return}let rows=listType(({recipes:'recipe',notes:'note',cars:'car'})[tab]);if(tab==='notes')rows=rows.filter(r=>(filter==='all'||(filter==='pinned'&&r.pinned)||(filter.startsWith('note:')&&noteCategory(r)===filteredCategory(filter)))).sort((a,b)=>noteUpdatedAt(b).localeCompare(noteUpdatedAt(a))||alpha(a,b));else if(tab==='cars')rows.sort((a,b)=>Number(a.status==='past')-Number(b.status==='past')||String(carOwnershipDate(b)).localeCompare(String(carOwnershipDate(a)))||alpha(a,b));else{if(filter.startsWith('recipe:'))rows=rows.filter(r=>recipeCategory(r)===filteredCategory(filter));rows.sort(byDate)}if(query){const q=query.toLowerCase();rows=rows.filter(r=>tab==='notes'?noteSearchText(r).toLowerCase().includes(q):tab==='recipes'?[r.title,...(r.recipeIngredients||[]).map(item=>ingredientName(item.ingredientId))].join('\n').toLowerCase().includes(q):[r.title,r.year,r.make,r.model,r.owner,r.vin].join('\n').toLowerCase().includes(q))}
if(!rows.length){const changed=commitList(`<div class="empty"><h2>${query?'No matches':({recipes:'What did you cook?',notes:'Make a little space.',cars:'Your garage starts here.'})[tab]}</h2><p>${query?'Try a different search.':({recipes:'Keep the ingredients, the good bits, and what you’d change next time.',notes:'Keep something useful.',cars:'Add a current car or a car you used to own.'})[tab]}</p>${query?'':'<button class="primary" id="emptyAdd">Add your first entry</button>'}</div>`);if(changed)$('#emptyAdd')?.addEventListener('click',()=>tab==='notes'?openNoteCreator():openEditor());return}
commitList(rows.map((r,i)=>{const divider=tab==='cars'&&r.status==='past'&&(i===0||rows[i-1].status!=='past')?'<h2 class="section-label">Previously owned</h2>':'';let meta=tab==='recipes'?[recipeCategory(r),dateLabel(r.date)].filter(Boolean).join(' • '):tab==='notes'?[noteCategory(r),noteUpdatedLabel(r)].filter(Boolean).join(' • '):[r.year,r.make,r.model].filter(Boolean).join(' ');const thumb=tab==='recipes'?photoSource(recipeCover(r),'tiny'):r.photos?.map(photo=>photoSource(photo,'tiny')).find(Boolean),bandColor=tab==='recipes'?recipeCardColor(i,rows.length):PALETTES[tab][Math.min(i,PALETTES[tab].length-1)];if(tab==='cars'){const cover=carCover(r),coverUrl=photoSource(cover,'thumb');return `${divider}<button class="car-card" data-open="${e(r.id)}"><span class="car-card-photo">${coverUrl?`<img src="${e(coverUrl)}" alt="${e(title(r))}" loading="lazy" decoding="async">`:`<span class="car-photo-placeholder">${icon('cars')}<span>Add a cover photo</span></span>`}${r.photos?.length?`<span class="photo-count">${r.photos.length} photo${r.photos.length===1?'':'s'}</span>`:''}</span><span class="car-card-copy"><strong>${e(title(r))}</strong><span>${e(meta)}</span>${r.owner?`<span class="small">${e(r.owner)}</span>`:''}</span></button>`}return `${divider}<button class="band ${isNoteHub(r)?'note-hub-band':''}" data-open="${e(r.id)}" style="--band:${bandColor}"><span class="copy"><strong>${r.pinned?pinIcon:''}${e(title(r))}</strong><span class="meta">${e(meta)}</span></span>${thumb?`<img class="thumb" src="${e(thumb)}" alt="" loading="lazy" decoding="async">`:''}</button>`}).join(''))}
function renderIngredientList(){let rows=ingredients().filter(item=>!item.hidden);if(query){const q=query.toLowerCase();rows=rows.filter(item=>[item.title,...(item.aliases||[]),...ingredientTagNames(item),plainRichText(item.body,item.richText),item.substitutes||''].join('\n').toLowerCase().includes(q))}if(!rows.length){const changed=commitList(`<div class="empty"><h2>${query?'No matches':'Build your ingredient library.'}</h2><p>${query?'Try a different search.':'Add ingredients once, then reuse them across recipes.'}</p>${query?'':'<button class="primary" id="emptyAdd">Add your first ingredient</button>'}</div>`);if(changed)$('#emptyAdd')?.addEventListener('click',()=>openEditor(null,'ingredient'));return}commitList(`<div class="ingredient-grid">${rows.map(item=>{const cover=ingredientCover(item),coverUrl=photoSource(cover,'thumb'),tags=ingredientTagNames(item);return `<button class="ingredient-card" data-open="${e(item.id)}"><span class="ingredient-card-photo">${coverUrl?`<img src="${e(coverUrl)}" alt="${e(item.title)}" loading="lazy" decoding="async">`:`<span class="ingredient-photo-placeholder ingredient-photo-drop" data-ingredient-photo-drop="${e(item.id)}">Drop photo here</span>`}</span><span class="ingredient-card-copy"><strong>${e(item.title)}</strong>${tags.length?`<span>${e(tags.join(' · '))}</span>`:''}</span></button>`}).join('')}</div>`)}
let suppressListClickUntil=0,categorySwipe=null;
function hubSearchTab(note,value){const q=String(value||'').toLowerCase();if(!q)return '';if(noteKind(note)==='homeManual'){if(flattenHubText(note.homeHistory).join(' ').toLowerCase().includes(q))return'maintenance';if(flattenHubText(note.homeContacts).join(' ').toLowerCase().includes(q))return'contacts';return'items'}if(noteKind(note)==='packing'){const trip=hubArray(note,'packingTrips').find(item=>flattenHubText(item).join(' ').toLowerCase().includes(q));return trip?`trip:${trip.id}`:'template'}const guide=hubArray(note,'photoGuides').find(item=>flattenHubText(item).join(' ').toLowerCase().includes(q));return guide?`guide:${guide.id}`:''}
function handleListOpen(event){if(performance.now()<suppressListClickUntil){event.preventDefault();event.stopPropagation();return}const list=$('#list'),button=event.target.closest?.('[data-open]');if(!button||!list.contains(button))return;event.preventDefault();event.stopPropagation();const closing=selected===button.dataset.open;selected=closing?null:button.dataset.open;if(!closing){const opened=get(selected);if(isNoteHub(opened)&&query)hubState(opened).tab=hubSearchTab(opened,query)}writeViewHistory();list.querySelectorAll('[data-open].selected').forEach(item=>item.classList.remove('selected'));if(!closing)button.classList.add('selected');try{renderDetail()}catch(error){console.error(error);toast('This entry could not be opened. Reload the app and try again.')}if(!closing&&matchMedia('(max-width:680px)').matches)scrollTo(0,0)}
function categorySwipeEligible(event){return matchMedia('(max-width:680px)').matches&&!selected&&categoryTabs().length>1&&event.button===0}
function resetCategorySwipe(){const list=$('#list');list.style.transition='transform 300ms cubic-bezier(0.37,0,0.63,1),opacity 300ms cubic-bezier(0.37,0,0.63,1)';list.style.transform='translate3d(0,0,0)';list.style.opacity='1';setTimeout(()=>{if(!categorySwipe){list.style.transition='';list.style.transform='';list.style.opacity=''}},300)}
function finishCategorySwipe(event){if(!categorySwipe||event.pointerId!==categorySwipe.pointerId)return;const state=categorySwipe;categorySwipe=null;const list=$('#list'),tabs=categoryTabs(),index=tabs.findIndex(([value])=>value===filter),threshold=Math.min(110,list.clientWidth*.18),direction=state.dx<0?1:-1,next=index+direction,commit=state.horizontal&&Math.abs(state.dx)>=threshold&&next>=0&&next<tabs.length;if(state.horizontal)suppressListClickUntil=performance.now()+450;if(!commit){resetCategorySwipe();return}filter=tabs[next][0];writeViewHistory();renderTools();renderList();list.style.transition='none';list.style.transform=`translate3d(${direction>0?'100%':'-100%'},0,0)`;list.style.opacity='.65';requestAnimationFrame(()=>requestAnimationFrame(resetCategorySwipe))}
function bindCategoryPaging(){const list=$('#list');list.addEventListener('pointerdown',event=>{if(!categorySwipeEligible(event))return;categorySwipe={pointerId:event.pointerId,startX:event.clientX,startY:event.clientY,dx:0,horizontal:false,vertical:false};list.setPointerCapture?.(event.pointerId)});list.addEventListener('pointermove',event=>{const state=categorySwipe;if(!state||event.pointerId!==state.pointerId||state.vertical)return;const dx=event.clientX-state.startX,dy=event.clientY-state.startY;if(!state.horizontal&&Math.abs(dy)>8&&Math.abs(dy)>Math.abs(dx)){state.vertical=true;return}if(!state.horizontal&&Math.abs(dx)>8&&Math.abs(dx)>Math.abs(dy))state.horizontal=true;if(!state.horizontal)return;event.preventDefault();const tabs=categoryTabs(),index=tabs.findIndex(([value])=>value===filter),atEdge=(dx>0&&index===0)||(dx<0&&index===tabs.length-1);state.dx=atEdge?dx*.24:dx;list.style.transition='none';list.style.transform=`translate3d(${state.dx}px,0,0)`;list.style.opacity=String(Math.max(.72,1-Math.abs(state.dx)/Math.max(1,list.clientWidth)*.2))});list.addEventListener('pointerup',finishCategorySwipe);list.addEventListener('pointercancel',event=>{if(categorySwipe?.pointerId!==event.pointerId)return;categorySwipe=null;resetCategorySwipe()})}
function photoMarkup(items=[],coverPhotoId=''){const ordered=items.map((item,index)=>({item,index}));if(coverPhotoId)ordered.sort((a,b)=>Number(photoKey(b.item)===coverPhotoId)-Number(photoKey(a.item)===coverPhotoId));return ordered.length?`<div class="photos">${ordered.map(({item,index},position)=>{const url=photoSource(item,'detail');return url?`<button class="photo-open" data-photo-index="${index}" style="padding:0;background:none" aria-label="View photo"><img src="${e(url)}" alt="Journal photo" loading="${position?'lazy':'eager'}" decoding="async"></button>`:'<p class="small">Photo is not available offline yet.</p>'}).join('')}</div>`:''}
const RICH_TAGS=new Set(['A','B','BLOCKQUOTE','BR','DIV','LI','OL','P','STRONG','UL']);
function sanitizeRichHTML(value){const template=document.createElement('template');template.innerHTML=String(value||'');const clean=parent=>{for(const child of [...parent.childNodes]){if(child.nodeType===Node.COMMENT_NODE){child.remove();continue}if(child.nodeType===Node.TEXT_NODE&&child.data.includes('\u200B'))child.data=child.data.replaceAll('\u200B','');if(child.nodeType!==Node.ELEMENT_NODE)continue;if(!RICH_TAGS.has(child.tagName)){clean(child);child.replaceWith(...child.childNodes);continue}const href=child.tagName==='A'?child.getAttribute('href'):'';for(const attribute of [...child.attributes])child.removeAttribute(attribute.name);if(child.tagName==='A')try{const url=new URL(href);if(!['http:','https:'].includes(url.protocol))throw Error();child.href=url.href;child.target='_blank';child.rel='noopener noreferrer'}catch{child.removeAttribute('href')}clean(child)}};clean(template.content);return template.innerHTML}
function linkifyRichHTML(value){const template=document.createElement('template');template.innerHTML=sanitizeRichHTML(value);const visit=parent=>{for(const child of [...parent.childNodes]){if(child.nodeType===Node.TEXT_NODE&&parent.tagName!=='A'&&/https?:\/\//.test(child.data)){const span=document.createElement('span');span.innerHTML=linkify(child.data);child.replaceWith(...span.childNodes)}else if(child.nodeType===Node.ELEMENT_NODE)visit(child)}};visit(template.content);return template.innerHTML}
function plainRichText(value,formatted=false){if(!formatted)return String(value||'');const node=document.createElement('div');node.innerHTML=sanitizeRichHTML(value);return node.textContent||''}
function reading(label,text,formatted=false){return text?`<h3>${label}</h3><div class="reading ${formatted?'rich-reading':''}">${formatted?linkifyRichHTML(text):linkify(text)}</div>`:''}
function maintenanceHistoryLabel(item){const completed=item.completedDate||item.completedAt?.slice(0,10),scheduled=item.scheduledDate;if(completed&&scheduled)return `Completed ${dateLabel(completed)} · originally due ${dateLabel(scheduled)}`;return completed?`Completed ${dateLabel(completed)}`:dateLabel(item.date)}
function recipeIngredientsMarkup(recipe){const rows=recipe.recipeIngredients||[];if(!rows.length)return '';return `<h3>Ingredients</h3><div class="recipe-ingredients-reading">${rows.map(item=>`<div class="recipe-ingredient-reading"><span class="ingredient-amount">${e(item.amount||'')}</span><button type="button" class="ingredient-link" data-ingredient-link="${e(item.ingredientId)}">${e(ingredientName(item.ingredientId))}</button><span class="ingredient-notes">${e(item.notes||'')}</span></div>`).join('')}</div>`}
function ingredientDetailMarkup(item){const tags=ingredientTagNames(item),linked=recipesUsing(item.id),aliases=(item.aliases||[]).filter(Boolean);return `<p class="sub ingredient-tags">${tags.length?tags.map(tag=>`<span>${e(tag)}</span>`).join(''):'Untagged'}${item.hidden?'<span>Hidden from Ingredients</span>':''}</p>${reading('Cooking notes',item.body,item.richText)}${reading('Substitutes',item.substitutes)}${aliases.length?`<h3>Also known as</h3><p>${e(aliases.join(' · '))}</p>`:''}<h3>Recipes</h3>${linked.length?`<div class="ingredient-recipes">${linked.map(recipe=>{const rows=recipe.recipeIngredients.filter(row=>row.ingredientId===item.id),context=rows.map(row=>[row.amount,row.notes].filter(Boolean).join(' · ')).filter(Boolean).join('; ');return `<button type="button" data-recipe-link="${e(recipe.id)}"><strong>${e(recipe.title)}</strong>${context?`<span>${e(context)}</span>`:''}</button>`}).join('')}</div>`:'<p class="small">No recipes use this ingredient yet.</p>'}`}
function handleDetailFoodNav(event){const ingredient=event.target.closest('[data-ingredient-link]'),recipe=event.target.closest('[data-recipe-link]');if(!ingredient&&!recipe)return;event.preventDefault();event.stopPropagation();foodView=ingredient?'ingredients':'recipes';selected=(ingredient||recipe).dataset[ingredient?'ingredientLink':'recipeLink'];query='';writeViewHistory();render()}
function handleDetailPhoto(event){const button=event.target.closest('[data-photo-index]');if(!button)return;event.preventDefault();event.stopPropagation();showPhoto(selected,Number(button.dataset.photoIndex))}
function sizeDetailTray(){const detail=$('#detail');if(!detail||detail.hidden||!matchMedia('(min-width:681px)').matches){detail?.style.removeProperty('--detail-max-height');return}const viewportHeight=window.visualViewport?.height||window.innerHeight,top=Math.max(120,detail.getBoundingClientRect().top),available=Math.max(120,Math.floor(viewportHeight-top-24));detail.style.setProperty('--detail-max-height',`${available}px`)}
const hubArray=(note,key)=>Array.isArray(note?.[key])?note[key]:[];
const hubState=note=>{if(!hubViewState.has(note.id))hubViewState.set(note.id,{tab:noteKind(note)==='homeManual'?'items':noteKind(note)==='packing'?'template':'',scrollTop:0});return hubViewState.get(note.id)};
const hubRich=value=>value?`<div class="reading rich-reading">${linkifyRichHTML(value)}</div>`:'';
const hubPhotos=(items,ownerId,captions=[])=>(items||[]).length?`<div class="hub-photo-strip">${items.map((photo,index)=>{const url=photoSource(photo,'thumb'),caption=captions[index]||'';return url?`<button type="button" data-hub-photo="${index}" data-hub-photo-owner="${e(ownerId)}"><img src="${e(url)}" alt="${e(caption)}" loading="lazy" decoding="async">${caption?`<span>${e(caption)}</span>`:''}</button>`:''}).join('')}</div>`:'';
function hubTabs(note,tabs){const state=hubState(note);if(!tabs.some(([key])=>key===state.tab))state.tab=tabs[0][0];return `<div class="hub-tabs" role="tablist">${tabs.map(([key,label,count])=>`<button type="button" class="${state.tab===key?'active':''}" data-hub-tab="${key}" role="tab" aria-selected="${state.tab===key}">${e(label)}${Number.isFinite(count)?` <span>${count}</span>`:''}</button>`).join('')}</div>`}
function homeHubMarkup(note){
 const state=hubState(note),items=hubArray(note,'homeItems'),history=hubArray(note,'homeHistory').slice().sort((a,b)=>String(b.completedDate||b.date||'').localeCompare(String(a.completedDate||a.date||''))),contacts=hubArray(note,'homeContacts');
 const tabs=hubTabs(note,[['items','Home',items.length],['maintenance','Maintenance',history.length],['contacts','Contacts',contacts.length]]);
 let content='';
 if(state.tab==='items')content=`<div class="hub-toolbar"><p>Rooms, appliances, systems, warranties, and useful records.</p><button class="primary" data-hub-action="add-home-item">Add item</button></div>${items.length?`<div class="hub-card-grid">${items.map(item=>`<article class="hub-card">${hubPhotos(item.photos,item.id)}<div class="hub-card-body"><p class="hub-kicker">${e([item.kind,item.location].filter(Boolean).join(' · ')||'Home item')}</p><h3>${e(item.title||'Untitled item')}</h3>${item.fields?.length?`<dl class="hub-facts">${item.fields.map(field=>`<div><dt>${e(field.label)}</dt><dd>${linkify(field.value)}</dd></div>`).join('')}</dl>`:''}${[item.purchaseDate&&`Purchased ${dateLabel(item.purchaseDate)}`,item.warrantyDate&&`Warranty until ${dateLabel(item.warrantyDate)}`,item.seller,item.price].filter(Boolean).length?`<p class="small">${e([item.purchaseDate&&`Purchased ${dateLabel(item.purchaseDate)}`,item.warrantyDate&&`Warranty until ${dateLabel(item.warrantyDate)}`,item.seller,item.price&&`$${item.price}`].filter(Boolean).join(' · '))}</p>`:''}${hubRich(item.body)}${item.links?.length?`<div class="hub-links">${item.links.map(link=>`<a href="${e(link.url)}" target="_blank" rel="noopener noreferrer">${e(link.label||link.url)}</a>`).join('')}</div>`:''}<div class="hub-card-actions"><button class="ghost" data-hub-action="edit-home-item" data-item-id="${e(item.id)}">Edit</button><button class="ghost" data-hub-action="home-todo" data-item-id="${e(item.id)}">Create To-Do</button><button class="danger text-button" data-hub-action="delete-home-item" data-item-id="${e(item.id)}">Delete</button></div></div></article>`).join('')}</div>`:'<div class="hub-empty"><h3>Start your home manual.</h3><p>Add a room, appliance, system, finish, or anything you may need to remember later.</p></div>'}`;
 if(state.tab==='maintenance')content=`<div class="hub-toolbar"><p>A single history across everything in your home.</p><button class="primary" data-hub-action="add-home-history">Log maintenance</button></div>${history.length?`<div class="hub-timeline">${history.map(item=>{const source=items.find(entry=>entry.id===item.itemId);return `<article><time>${e(dateLabel(item.completedDate||item.date))}</time><div><h3>${e(item.title||'Maintenance')}</h3><p class="small">${e([source?.title,item.provider,item.cost&&`$${item.cost}`].filter(Boolean).join(' · '))}</p>${item.scheduledDate?`<p class="small">Originally due ${e(dateLabel(item.scheduledDate))}</p>`:''}${hubRich(item.body)}<button class="ghost" data-hub-action="edit-home-history" data-item-id="${e(item.id)}">Edit</button><button class="danger text-button" data-hub-action="delete-home-history" data-item-id="${e(item.id)}">Delete</button></div></article>`}).join('')}</div>`:'<div class="hub-empty"><h3>No maintenance history yet.</h3><p>Completed linked To-Dos can be added here automatically.</p></div>'}`;
 if(state.tab==='contacts')content=`<div class="hub-toolbar"><p>Tradespeople, shops, utilities, and other home contacts.</p><button class="primary" data-hub-action="add-home-contact">Add contact</button></div>${contacts.length?`<div class="hub-card-grid compact">${contacts.map(item=>`<article class="hub-card"><div class="hub-card-body"><p class="hub-kicker">${e(item.role||'Contact')}</p><h3>${e(item.name||'Untitled contact')}</h3>${item.phone?`<a href="tel:${e(item.phone)}">${e(item.phone)}</a>`:''}${item.email?`<a href="mailto:${e(item.email)}">${e(item.email)}</a>`:''}${item.url?`<a href="${e(item.url)}" target="_blank" rel="noopener noreferrer">Website</a>`:''}${hubRich(item.body)}<div class="hub-card-actions"><button class="ghost" data-hub-action="edit-home-contact" data-item-id="${e(item.id)}">Edit</button><button class="danger text-button" data-hub-action="delete-home-contact" data-item-id="${e(item.id)}">Delete</button></div></div></article>`).join('')}</div>`:'<div class="hub-empty"><h3>No contacts yet.</h3><p>Keep the people and providers you trust close at hand.</p></div>'}`;
 return `${tabs}<div class="hub-panel">${content}</div>`;
}
const packingAlpha=(a,b)=>String(a.title||'').localeCompare(String(b.title||''),undefined,{sensitivity:'base'})||String(a.category||'').localeCompare(String(b.category||''),undefined,{sensitivity:'base'});
function packingTemplateItems(note){const source=Array.isArray(note?.packingTemplate)?note.packingTemplate:hubArray(note,'packingPacks').flatMap((pack,packIndex)=>(pack.sections||[]).flatMap((section,sectionIndex)=>(section.items||[]).map((item,itemIndex)=>({...item,id:item.id||`legacy_template_${packIndex}_${sectionIndex}_${itemIndex}`,category:section.title||'General'}))));const seen=new Set(),result=[];for(const item of source){const title=String(item?.title||'').trim(),category=String(item?.category||'General').trim()||'General',key=`${category.toLocaleLowerCase()}\n${title.toLocaleLowerCase()}`;if(!title||seen.has(key))continue;seen.add(key);result.push({id:item.id||crypto.randomUUID(),category,title})}return result.sort(packingAlpha)}
function packingTripItems(trip){const source=Array.isArray(trip?.items)?trip.items:(trip?.sections||[]).flatMap((section,sectionIndex)=>(section.items||[]).map((item,itemIndex)=>({...item,id:item.id||`legacy_trip_${sectionIndex}_${itemIndex}`,category:section.title||'General',done:!!item.packed})));return source.map(item=>({id:item.id||crypto.randomUUID(),category:String(item.category||'General').trim()||'General',title:String(item.title||'').trim(),done:!!(item.done??item.packed)})).filter(item=>item.title)}
function normalizedPackingTrip(trip){const next={...trip,title:String(trip?.title||'Trip').trim()||'Trip',items:packingTripItems(trip),hideCompleted:trip?.hideCompleted!==false};delete next.sections;delete next.packId;delete next.date;delete next.body;delete next.forgot;delete next.unused;delete next.richText;return next}
function packingTemplateRow(item={}){return `<div class="packing-template-row" data-packing-template-id="${e(item.id||crypto.randomUUID())}"><input name="packingCategory" value="${e(item.category||'')}" list="packing-category-options" maxlength="100" placeholder="Category" aria-label="Category" required><input name="packingTitle" value="${e(item.title||'')}" maxlength="300" placeholder="Item name" aria-label="Item name" required><button type="button" class="text-button packing-template-remove" aria-label="Remove item">×</button></div>`}
