 const close=async()=>{if(submitting)return;if(dirty&&!await ask('Discard changes?','Your unsaved changes will be lost.','Discard',true))return;d.close()};d.querySelectorAll('[data-close]').forEach(button=>button.onclick=close);d.oncancel=event=>{event.preventDefault();close()};
