  if(action==='add-home-item')return openHomeItemEditor(note);if(action==='edit-home-item')return openHomeItemEditor(note,hubArray(note,'homeItems').find(item=>item.id===id));if(action==='delete-home-item')return deleteHubItem(note,'homeItems',id,'home item');
  if(action==='add-home-history')return openHomeHistoryEditor(note);if(action==='edit-home-history')return openHomeHistoryEditor(note,hubArray(note,'homeHistory').find(item=>item.id===id));if(action==='delete-home-history')return deleteHubItem(note,'homeHistory',id,'maintenance record');
