function recipeIngredientEditor(recipe){const rows=recipe.recipeIngredients?.length?recipe.recipeIngredients:[{}];return `<fieldset class="recipe-ingredient-editor"><legend>Ingredients</legend><div id="recipeIngredientRows">${rows.map(recipeIngredientRow).join('')}</div><button type="button" class="secondary" id="addIngredientRow">Add ingredient</button></fieldset>`}
