function ingredientHero(r){const cover=ingredientCover(r),url=photoSource(cover,'detail');return url?`<button class="ingredient-hero" data-photo-index="0" aria-label="Open photo of ${e(title(r))}"><img src="${e(url)}" alt="${e(title(r))}" decoding="async"></button>`:`<div class="ingredient-hero ingredient-hero-empty ingredient-photo-drop" data-ingredient-photo-drop="${e(r.id)}">Drop photo here</div>`}
function carOwnership(r){if(r.status==='past')return r.ownedFrom?`Owned ${dateLabel(r.ownedFrom)}${r.ownedTo?' – '+dateLabel(r.ownedTo):''}`:r.ownedTo?`Owned until ${dateLabel(r.ownedTo)}`:'Previously owned';return r.ownedFrom?`Owned since ${dateLabel(r.ownedFrom)}`:'Currently owned'}
function carHero(r){const cover=carCover(r),url=photoSource(cover,'detail');return url?`<button class="car-hero" data-photo-index="${r.photos.indexOf(cover)}" aria-label="Open photos of ${e(title(r))}"><img src="${e(url)}" alt="${e(title(r))}" decoding="async"><span class="photo-count">View ${r.photos.length===1?'photo':r.photos.length+' photos'}</span></button>`:''}
function carGallery(r){return `<div class="car-gallery">${(r.photos||[]).map((photo,index)=>{const url=photoSource(photo,'tiny');return url?`<button class="car-gallery-thumb ${photo===carCover(r)?'is-cover':''}" data-photo-index="${index}" aria-label="View photo ${index+1}${photo===carCover(r)?', cover photo':''}"><img src="${e(url)}" alt="" loading="lazy" decoding="async"></button>`:''}).join('')}</div><button class="ghost" id="addCarPhotos">Add photos</button>`}
let photoViewerState=null;
const prefetchedPhotoUrls=new Set();
function prefetchAdjacentPhotos(record,index){if(!record?.photos?.length||record.photos.length<2)return;const indexes=[(index-1+record.photos.length)%record.photos.length,(index+1)%record.photos.length];const run=()=>{for(const nextIndex of new Set(indexes)){const url=photoSource(record.photos[nextIndex],'lightbox');if(!url||prefetchedPhotoUrls.has(url))continue;prefetchedPhotoUrls.add(url);const image=new Image();image.decoding='async';image.src=url}};if(window.requestIdleCallback)window.requestIdleCallback(run);else window.setTimeout(run,0)}
function showPhoto(recordId,index=0,recordOverride=null){
 const r=recordOverride||get(recordId);if(!r?.photos?.length)return;
 let d=$('#photoViewer');
 if(!d){d=document.createElement('dialog');d.id='photoViewer';d.className='photo-viewer';d.setAttribute('aria-label','Photo gallery');document.body.append(d);
  d.addEventListener('close',()=>{photoViewerState=null;d.replaceChildren()});
  d.addEventListener('keydown',ev=>{if(ev.key==='ArrowLeft'||ev.key==='ArrowRight'){ev.preventDefault();stepPhoto(ev.key==='ArrowLeft'?-1:1)}});
 }
 photoViewerState={recordId,index,record:recordOverride};renderPhotoViewer();d.showModal();if(!recordOverride)selected=recordId;
}
function showNestedHubPhoto(note,index,ownerId){const item=hubArray(note,'homeItems').find(entry=>entry.id===ownerId)||hubArray(note,'photoGuides').find(entry=>entry.id===ownerId);if(!item?.photos?.length)return;showPhoto(note.id,index,{id:`${note.id}_${ownerId}`,type:'noteHubPhoto',title:item.title||note.title,photos:item.photos})}
function stepPhoto(direction){if(!photoViewerState)return;const r=photoViewerState.record||get(photoViewerState.recordId);if(!r?.photos?.length)return;photoViewerState.index=(photoViewerState.index+direction+r.photos.length)%r.photos.length;renderPhotoViewer(direction<0?'previousPhoto':'nextPhoto')}
function renderPhotoViewer(focusId){
 const state=photoViewerState,d=$('#photoViewer');if(!state||!d)return;
 const r=state.record||get(state.recordId);if(!r?.photos?.length||r.deleted){if(d.open)d.close();return}
 state.index=Math.min(state.index,r.photos.length-1);const photo=r.photos[state.index],url=photoSource(photo,'lightbox'),canChooseCover=['car','recipe'].includes(r.type),cover=canChooseCover&&photoKey(entryCover(r))===photoKey(photo);
 d.innerHTML=`<div class="photo-viewer-toolbar"><div>${canChooseCover?(cover?'<span class="cover-badge">Cover Photo</span>':'<button class="primary" id="setCoverPhoto">Set as Cover Photo</button>'):`<span>${e(title(r))}</span>`}</div><button class="text-button" id="closePhoto" aria-label="Close photo gallery">×</button></div><div class="photo-viewer-stage">${url?`<img src="${e(url)}" alt="${e(title(r))}, photo ${state.index+1}">`:'<p>Photo is not available offline yet.</p>'}<button class="photo-arrow previous" id="previousPhoto" aria-label="Previous photo" ${r.photos.length<2?'hidden':''}>&lt;</button><button class="photo-arrow next" id="nextPhoto" aria-label="Next photo" ${r.photos.length<2?'hidden':''}>&gt;</button></div><p class="photo-position" aria-live="polite">${state.index+1} / ${r.photos.length}</p>`;
 $('#closePhoto').onclick=()=>d.close();$('#previousPhoto').onclick=()=>stepPhoto(-1);$('#nextPhoto').onclick=()=>stepPhoto(1);
 const currentImage=d.querySelector('.photo-viewer-stage img'),prefetch=()=>prefetchAdjacentPhotos(r,state.index);if(currentImage?.complete&&currentImage.naturalWidth)prefetch();else currentImage?.addEventListener('load',prefetch,{once:true});
 $('#setCoverPhoto')?.addEventListener('click',async ev=>{ev.currentTarget.disabled=true;try{const latest=get(state.recordId);if(!latest||latest.deleted||!latest.photos?.some(p=>photoKey(p)===photoKey(photo)))throw Error('This photo is no longer attached to the entry.');selected=state.recordId;await save({...latest,coverPhotoId:photoKey(photo)});if(photoViewerState===state&&d.open)renderPhotoViewer('closePhoto');toast('Cover photo updated · syncing')}catch(err){toast(err.message);if(photoViewerState===state&&d.open)renderPhotoViewer('setCoverPhoto')}});
 if(focusId)document.getElementById(focusId)?.focus();
}
function todoSettingsCard(){const schedules=listType('todoSchedule').filter(schedule=>!schedule.cancelledOn);return `<section class="setting-card" style="--band:#e05c68"><h2>To-Do settings</h2><h3>Reminders</h3>${schedules.length?`<div class="setting-reminders">${schedules.map(schedule=>`<div class="setting-reminder"><div><strong>${e(schedule.title)}</strong><span>Every ${schedule.intervalMonths} month${schedule.intervalMonths===1?'':'s'} · Next ${e(dateLabel(nextScheduleDate(schedule)))}</span></div><button class="ghost" data-cancel-schedule="${e(schedule.id)}">Cancel</button></div>`).join('')}</div>`:'<p class="small">No recurring reminders.</p>'}</section>`}
function renderSettings(){$('#settings').innerHTML=`<div class="setting-grid"><div><section class="setting-card" style="--band:#4c889c"><h2>Account & sync</h2><p>${e(user?.email||'Sign in with your Google account.')}</p><p class="small">${e(lastSyncError||'Red Ridge connects to your red-ridge-d47fa Firebase project.')}</p>${failedOps.length?'<button class="primary" id="retryFailed">Retry rejected changes</button>':''}<button class="ghost" id="signOut">Sign out & clear this device</button></section><section class="setting-card" style="--band:#b85f4b"><h2>Cloudinary photos</h2><p>Protected signed uploads are enabled.</p><p class="small">Red Ridge verifies your Firebase account before authorizing each upload. Photos still use standard Cloudinary delivery URLs that can be opened by anyone who obtains the link.</p></section></div><div>${todoSettingsCard()}<section class="setting-card" style="--band:#d2a64c"><h2>Backup & restore</h2><p>Export your entries and Cloudinary photo references as a JSON file.</p><p class="small">Entry text is readable in the backup. Keep it somewhere private. Import adds missing entries; existing IDs are kept.</p><button class="primary" id="export">Export backup</button><button class="secondary" id="import">Import backup</button><input id="importFile" type="file" accept="application/json,.json" hidden><p id="backupStatus" class="small"></p></section><section class="setting-card" style="--band:#4f8791"><h2>Offline & installation</h2><p>${trusted?'Offline saving is enabled on this trusted device.':'Offline saving is off on this device.'}</p><p class="small">${trusted?'Open Red Ridge online once to cache the app and journal. Text changes queue while offline and sync when you reconnect. New photo uploads require a connection.':'Enable it to keep your journal and queued changes through restarts. Use only on your own device.'}</p><button class="secondary" id="offlineToggle">${trusted?'Turn off offline saving':'Enable offline saving'}</button><button class="ghost" id="install">Install Red Ridge</button><p class="small">Notifications are not enabled. Maintenance reminders live in Cars.</p><p class="small" id="swState"></p></section></div></div>`;
$('#retryFailed')?.addEventListener('click',async()=>{const ops=failedOps;failedOps=[];await persist(ops);renderSettings()});$$('[data-cancel-schedule]').forEach(button=>button.onclick=()=>cancelSchedule(get(button.dataset.cancelSchedule)));$('#signOut').onclick=async()=>{if(pending||failedOps.length||lastSyncError.includes('queued')){toast('Reconnect and wait for your changes to sync before signing out.');return}if(!await ask('Sign out?','Your offline copy will be removed from this device. Your synced journal stays in Firebase.','Sign out'))return;try{await cloud.signOut();location.reload()}catch(err){toast('Close other Red Ridge tabs, then reload to finish clearing this device. '+(err.code||''))}};
$('#export').onclick=exportBackup;$('#import').onclick=()=>$('#importFile').click();$('#importFile').onchange=importBackup;$('#offlineToggle').onclick=async()=>{if(pending||failedOps.length){toast('Wait for changes to sync first.');return}if(!await ask(trusted?'Turn off offline saving?':'Enable offline saving?',trusted?'Sign out and clear this device first. You can sign in again without offline saving.':'A copy of your journal will remain on this device. Only enable this on a private device.','Continue'))return;try{await cloud.signOut();localStorage.setItem('red-ridge-trusted',String(!trusted));location.reload()}catch{toast('Close other Red Ridge tabs and try again.')}};$('#install').onclick=install;$('#swState').textContent='Service worker: '+('serviceWorker' in navigator?(navigator.serviceWorker.controller?'active':'ready after the first reload'):'not supported by this browser');}
async function exportBackup(){if(!loaded||!photoLoaded){toast('Wait for entries and photos to finish loading.');return}const legacy=new Map(),active=records.filter(r=>!r.deleted).map(record=>{const copy=structuredClone(record);copy.photos=(copy.photos||[]).map(photo=>{if(typeof photo==='string'){const stored=photos.get(photo);if(stored)legacy.set(photo,stored);return photo}if(photo.url?.startsWith('data:image/jpeg;base64,')){legacy.set(photo.id,{id:photo.id,data:photo.url});return photo.id}return photo});return copy});const missing=active.flatMap(r=>r.photos||[]).filter(photo=>typeof photo==='string'&&!legacy.has(photo));if(missing.length){toast('Some legacy photos are not cached. Connect before exporting.');return}const data={app:'red-ridge',version:1,exportedAt:new Date().toISOString(),records:active,photos:[...legacy.values()]};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`red-ridge-backup-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')}
async function importBackup(ev){const file=ev.target.files[0];if(!file)return;try{if(file.size>100*1024*1024)throw Error('Choose a backup smaller than 100 MB.');const data=validateBackup(JSON.parse(await file.text()));const existing=new Set(records.map(r=>r.id));const fresh=data.records.filter(r=>!existing.has(r.id));if(!fresh.length){toast('All entries are already in this journal.');return}if(!await ask('Import backup?',`Add ${fresh.length} entries? Existing entries will be kept.`,'Import'))return;const ids=new Set(fresh.flatMap(r=>r.photos||[]));const ops=data.photos.filter(p=>ids.has(p.id)&&!photos.has(p.id)).map(p=>({collection:'photos',id:p.id,value:p})).concat(fresh.map(r=>({id:r.id,value:r})));let batch=[],size=0;for(const op of ops){const n=JSON.stringify(op).length;if(batch.length>=200||size+n>4000000){await persist(batch);batch=[];size=0}batch.push(op);size+=n}if(batch.length)await persist(batch);toast(`Imported ${fresh.length} entries`)}catch(err){toast(err.message)}finally{ev.target.value=''}}
async function install(){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('Use your browser menu → Install app or Add to Home Screen.')}
window.addEventListener('beforeinstallprompt',ev=>{ev.preventDefault();installPrompt=ev});window.addEventListener('online',()=>{lastSyncError='';syncStatus()});window.addEventListener('offline',syncStatus);window.addEventListener('resize',sizeDetailTray);window.visualViewport?.addEventListener('resize',sizeDetailTray);
initializeViewHistory();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{$('#gateStatus').textContent='Offline installation is unavailable in this browser. Online use still works.'});
initCloud().catch(()=>{});
window.addEventListener('beforeunload',event=>{if(failedOps.length||(!trusted&&pending)){event.preventDefault();event.returnValue=''}});
